curl -X POST https://apx.didit.me/auth/v2/programmatic/register/ \
  -H "Content-Type: application/json" \
  -d '{
    "email": "you@yourdomain.com",
    "password": "MyStr0ng!Pass"
  }'

import Didit from "@didit-protocol/sdk-node";

// This call needs no API key.
const didit = new Didit();

const result = await didit.account.register({
  email: "you@yourdomain.com",
  password: "MyStr0ng!Pass",
});
console.log(result);

ctx := context.Background()
// This call needs no API key.
client := didit.NewClient()

result, err := client.Account.Register(ctx, didit.RegisterRequest{
	Email:    "you@yourdomain.com",
	Password: "MyStr0ng!Pass",
})
if err != nil {
	log.Fatal(err)
}
fmt.Printf("%+v\n", result)

import me.didit.Didit;
import me.didit.types.RegisterRequest;

// This call needs no API key.
Didit client = new Didit();

var result = client.account().register(RegisterRequest.builder()
        .email("you@yourdomain.com")
        .password("MyStr0ng!Pass")
        .build());
System.out.println(result);

using System;
using System.Text.Json;
using Didit;

// This call needs no API key.
using var client = new DiditClient();

var result = await client.Account.RegisterAsync(new RegisterRequest
{
    Email = "you@yourdomain.com",
    Password = "MyStr0ng!Pass",
});
Console.WriteLine(JsonSerializer.Serialize(result));

