import Didit from "@didit-protocol/sdk-node";

// Use the access token that account.login returns.
const didit = new Didit({ accountToken: "YOUR_ACCESS_TOKEN" });

for await (const item of didit.account.organizations.list()) {
  console.log(item);
}

ctx := context.Background()
// Use the access token that account.login returns.
client := didit.NewClient(option.WithAccountToken("YOUR_ACCESS_TOKEN"))

iter := client.Account.Organizations.ListAutoPaging(ctx, didit.AccountOrganizationsListParams{})
for iter.Next() {
	fmt.Printf("%+v\n", iter.Current())
}
if err := iter.Err(); err != nil {
	log.Fatal(err)
}

