import Didit from "@didit-protocol/sdk-node";

// Use the access token that account.login returns.
const didit = new Didit({ accountToken: "YOUR_ACCESS_TOKEN" });

const result = await didit.account.applications.create("a1b2c3d4-5678-90ab-cdef-111111111111", {
  name: "Acme Customer App",
  website_url: "https://acme.example",
  redirect_uris: ["https://acme.example/callback"],
  terms_url: "https://acme.example/terms",
  privacy_url: "https://acme.example/privacy",
});
console.log(result);

