	Name:         didit.String("Acme Customer App"),
	WebsiteURL:   didit.String("https://acme.example"),
	RedirectURIs: didit.Some([]string{"https://acme.example/callback"}),
	TermsURL:     didit.String("https://acme.example/terms"),
	PrivacyURL:   didit.String("https://acme.example/privacy"),
})
if err != nil {
	log.Fatal(err)
}
